// Transcrição para o LLM. Os ids dos clientes viram "Cliente 1, 2...":
// o resumo não precisa saber QUEM disse (minimização de dados).
const conversas = $('Conversas da semana').first().json.conversas || [];
const LIMITE = 30000; // caracteres: protege contexto e cota do modelo
const partes = conversas.map((c, i) =>
  `### Cliente ${i + 1}\n` +
  c.mensagens.map(m => `${m.papel === 'user' ? 'Cliente' : 'Assistente'}: ${m.texto}`).join('\n'));
let transcricao = partes.join('\n\n');
if (transcricao.length > LIMITE) {
  transcricao = '[...conversas mais antigas omitidas...]\n' + transcricao.slice(-LIMITE);
}
return [{ json: { transcricao, total_conversas: conversas.length } }];

